-- Wisdom Library expansion: 100 new, published, slug-idempotent articles.
-- Existing rows, IDs, tags, images, read/bookmark relations and timestamps are preserved.
WITH articles (slug, title, excerpt, category, read_time_minutes, is_featured, practical_guidance) AS (
  VALUES
  ('five-elements-reference','The Five Elements: A Traditional Ayurveda Reference','A careful introduction to the traditional language of earth, water, fire, air, and space.','Ayurveda Fundamentals',5,true,'Use the five-element model as a reflection tool for routines and preferences, not as a diagnosis or a replacement for clinical assessment.'),
  ('ayurveda-and-modern-care','Ayurveda Alongside Modern Health Care','How to keep traditional self-care separate from diagnosis and treatment decisions.','Ayurveda Fundamentals',5,false,'Bring a complete list of supplements, therapies, and health goals to a licensed clinician before combining approaches.'),
  ('ayurvedic-language-guide','A Plain-Language Guide to Ayurvedic Terms','Common terms explained with respectful context and practical limits.','Ayurveda Fundamentals',4,false,'Write down unfamiliar terms and ask a qualified practitioner to explain how a recommendation fits your circumstances.'),
  ('understanding-gunas','Understanding the Gunas','A traditional introduction to sattva, rajas, and tamas without assigning moral value.','Ayurveda Fundamentals',5,false,'Notice which activities leave you settled or overstimulated, then make one modest routine adjustment at a time.'),
  ('ayurvedic-self-observation','Ayurvedic Self-Observation Without Self-Diagnosis','How to observe daily patterns while knowing when symptoms need medical attention.','Ayurveda Fundamentals',5,false,'Track sleep, meals, mood, and energy for a week; seek care for persistent, severe, or worsening symptoms.'),
  ('traditional-care-boundaries','Boundaries of Traditional Wellness Advice','Why wellness education cannot replace screening, diagnosis, or emergency care.','Ayurveda Fundamentals',4,false,'Use urgent or emergency services for alarming symptoms instead of delaying care while trying a wellness practice.'),
  ('ayurveda-history-and-context','Ayurveda: History, Context, and Respectful Learning','A concise historical orientation for new learners.','Ayurveda Fundamentals',6,false,'Learn from transparent sources that distinguish historical tradition, personal experience, and modern evidence.'),
  ('asking-about-ayurveda','Questions to Ask Before Trying Ayurvedic Care','A practical conversation guide for consumers.','Ayurveda Fundamentals',4,false,'Ask about qualifications, ingredients, product testing, costs, possible interactions, and when conventional care is needed.'),
  ('ayurveda-evidence-literacy','Reading Ayurveda Claims With Evidence Literacy','How to evaluate broad wellness promises and study headlines.','Ayurveda Fundamentals',6,false,'Prefer claims that name limits and risks; be cautious of products that promise to cure multiple unrelated conditions.'),
  ('dosha-as-traditional-framework','Doshas as a Traditional Framework','What Vata, Pitta, and Kapha mean in traditional teaching.','Doshas & Prakriti',5,true,'Treat dosha descriptions as a cultural wellness framework rather than a validated medical classification.'),
  ('prakriti-and-vikriti','Prakriti and Vikriti: Traditional Meanings','A non-diagnostic explanation of constitution and temporary imbalance concepts.','Doshas & Prakriti',5,false,'Avoid using a quiz result to explain away pain, fatigue, weight change, or other symptoms that deserve assessment.'),
  ('vata-traditional-profile','Vata: A Traditional Profile','Common Vata descriptions and gentle routine ideas.','Doshas & Prakriti',5,false,'Choose predictable meals, rest, and movement if they feel supportive, while adapting to your actual schedule and medical needs.'),
  ('pitta-traditional-profile','Pitta: A Traditional Profile','Common Pitta descriptions and calming routine ideas.','Doshas & Prakriti',5,false,'Use comfortable cooling habits such as shade, hydration, and regular breaks without treating heat intolerance as a dosha issue alone.'),
  ('kapha-traditional-profile','Kapha: A Traditional Profile','Common Kapha descriptions and steady activity ideas.','Doshas & Prakriti',5,false,'Build activity gradually and choose movement you enjoy; breathlessness, swelling, or sudden fatigue needs clinical attention.'),
  ('dosha-quiz-limitations','What a Dosha Quiz Can and Cannot Tell You','Why wellness quizzes are not diagnostic tools.','Doshas & Prakriti',4,false,'Use quiz results for curiosity, not to decide on medicines, restrictive diets, or whether to seek care.'),
  ('seasonal-dosha-reflection','Seasonal Dosha Reflection','Using seasonal change as a prompt for practical self-care.','Doshas & Prakriti',4,false,'Review clothing, hydration, meals, activity, and sleep as weather changes rather than relying on a fixed label.'),
  ('dosha-and-personal-preference','Dosha Language and Personal Preference','How to keep individual experience central to wellness choices.','Doshas & Prakriti',4,false,'Keep what is safe and useful, and drop a routine that is burdensome, painful, or inconsistent with medical advice.'),
  ('dosha-conversations-with-clinicians','Discussing Dosha Interests With Your Clinician','A respectful way to include traditional interests in care conversations.','Doshas & Prakriti',4,false,'Share exact product names and practices so your clinician can help identify safety concerns or interactions.'),
  ('balanced-plate-with-ayurveda','A Balanced Plate With Ayurvedic Inspiration','Pairing familiar food traditions with broadly accepted nutrition principles.','Food & Nutrition',6,true,'Build meals around a variety of vegetables, fruit, pulses, whole grains, and suitable protein sources, adjusted for culture and access.'),
  ('mindful-eating-basics','Mindful Eating Basics','Simple attention practices for meals without rigid food rules.','Food & Nutrition',4,false,'Sit when possible, reduce distractions for one meal, and pause to notice hunger and fullness without judgment.'),
  ('seasonal-produce-guide','Seasonal Produce as a Meal Planning Tool','A practical approach to variety, affordability, and food safety.','Food & Nutrition',4,false,'Choose available produce, wash it safely, and use frozen or canned options when they fit your budget and preferences.'),
  ('spices-in-everyday-cooking','Spices in Everyday Cooking','Flavor-focused ways to use culinary spices without medical promises.','Food & Nutrition',4,false,'Use spices for taste and enjoyment; do not substitute concentrated supplements for prescribed treatment.'),
  ('hydration-without-hype','Hydration Without Hype','Practical hydration habits and common myths.','Food & Nutrition',4,false,'Drink regularly according to thirst, climate, activity, and clinician guidance; fluid needs can differ with kidney or heart conditions.'),
  ('meal-regularity-guide','Meal Regularity: Finding a Sustainable Pattern','How consistent meal timing can support daily planning.','Food & Nutrition',5,false,'Plan a realistic eating rhythm around work, appetite, medicines, and medical dietary advice rather than forcing a schedule.'),
  ('food-safety-home-kitchen','Food Safety in the Home Kitchen','Safe storage and preparation belong in every wellness routine.','Food & Nutrition',5,false,'Wash hands, separate raw and ready-to-eat foods, cook thoroughly, and refrigerate leftovers promptly.'),
  ('fiber-and-food-variety','Fiber and Food Variety','A food-first overview of varied plant foods.','Food & Nutrition',5,false,'Increase fiber-rich foods gradually and drink fluids; ask a clinician for individualized advice with digestive disease or restrictions.'),
  ('nutrition-claims-and-supplements','Nutrition Claims and Supplements','How to distinguish food guidance from supplement marketing.','Food & Nutrition',5,false,'Check labels, avoid megadose claims, and discuss supplements with a pharmacist or clinician when you take medicines.'),
  ('morning-routine-flexible','A Flexible Morning Routine','A realistic daily-routine template rather than a rigid ideal.','Dinacharya (Daily Routine)',5,true,'Choose one anchor such as waking, washing, breakfast, or a short walk and adjust it to your sleep and care needs.'),
  ('tongue-cleaning-safety','Tongue Cleaning: Hygiene and Safety','Traditional oral-care context with simple safety limits.','Dinacharya (Daily Routine)',4,false,'Use gentle pressure and stop if there is bleeding, pain, or a persistent mouth change; seek dental advice when needed.'),
  ('oil-pulling-evidence-and-safety','Oil Pulling: Evidence and Safety','What to consider before adding this traditional practice.','Dinacharya (Daily Routine)',5,false,'Do not swallow oil, do not use it instead of brushing or dental care, and stop if it causes irritation or aspiration risk.'),
  ('abhyanga-at-home-safety','Abhyanga at Home: A Safety-First Guide','How to approach self-massage as comfort care.','Dinacharya (Daily Routine)',5,false,'Patch-test products, prevent slips, avoid broken skin, and ask a clinician before massage with a clotting or circulation condition.'),
  ('daily-sunlight-and-routine','Daylight and Daily Routine','Using daylight exposure as a cue for a steadier day.','Dinacharya (Daily Routine)',4,false,'Seek comfortable outdoor light when practical while protecting skin and following medical advice about photosensitivity.'),
  ('digital-sunset-routine','Creating a Digital Sunset Routine','A gentle evening transition away from screens.','Dinacharya (Daily Routine)',4,false,'Try a short device-free interval before bed and replace it with a low-stimulation activity you can maintain.'),
  ('daily-walking-habit','Building a Daily Walking Habit','A low-barrier movement habit for many adults.','Dinacharya (Daily Routine)',5,false,'Start with a safe, comfortable duration and pace; consult a clinician before a new activity plan if you have symptoms or limitations.'),
  ('routine-after-disruption','Returning to Routine After Disruption','How to restart after travel, illness, or a busy period.','Dinacharya (Daily Routine)',4,false,'Restart one anchor at a time and allow recovery needs to guide your pace after illness or major stress.'),
  ('ritucharya-spring','Spring Routine: Traditional Seasonal Reflection','A gentle spring planning guide grounded in ordinary self-care.','Ritucharya (Seasonal Wellness)',5,false,'Refresh meals, activity, and sleep gradually while considering local weather, allergies, and your own health needs.'),
  ('ritucharya-summer','Summer Routine: Heat-Smart Self-Care','Seasonal comfort practices without medical claims.','Ritucharya (Seasonal Wellness)',5,true,'Use shade, regular fluids, breathable clothing, and rest breaks; seek urgent care for signs of heat illness.'),
  ('ritucharya-monsoon','Monsoon Routine: Food and Movement Planning','Adapting routines during wet weather and changing schedules.','Ritucharya (Seasonal Wellness)',5,false,'Prioritize food hygiene, safe walking surfaces, and indoor movement options when weather limits outdoor plans.'),
  ('ritucharya-autumn','Autumn Routine: A Gentle Transition','Practical habits for changing light and temperatures.','Ritucharya (Seasonal Wellness)',4,false,'Review layers, sleep timing, and meal planning as days change, and seek care for persistent seasonal symptoms.'),
  ('ritucharya-winter','Winter Routine: Warmth, Movement, and Connection','A practical winter wellness checklist.','Ritucharya (Seasonal Wellness)',5,false,'Plan warm meals, safe movement, social connection, and appropriate clothing while following local public-health advice.'),
  ('seasonal-allergy-care','Seasonal Allergy Care: When Wellness Is Not Enough','Self-care boundaries for allergy symptoms.','Ritucharya (Seasonal Wellness)',5,false,'Use clinician-recommended allergy management and seek urgent help for breathing difficulty, swelling, or severe reactions.'),
  ('weather-and-exercise-safety','Weather and Exercise Safety','How to adapt activity to heat, cold, rain, and air quality.','Ritucharya (Seasonal Wellness)',5,false,'Check conditions, choose safer times and locations, and stop for dizziness, chest pain, or unusual breathlessness.'),
  ('seasonal-meal-planning','Seasonal Meal Planning Without Restriction','Using seasons for variety instead of restrictive rules.','Ritucharya (Seasonal Wellness)',4,false,'Choose accessible foods and retain adequate nutrition; get professional help before major dietary restriction.'),
  ('herbal-product-safety-basics','Herbal Product Safety Basics','What to check before using herbs or botanical supplements.','Herbs & Botanicals',6,true,'Discuss products with a pharmacist or clinician, especially during pregnancy, breastfeeding, chronic illness, or when taking medicines.'),
  ('ashwagandha-safety-guide','Ashwagandha: Questions to Ask First','A safety-oriented consumer guide to a commonly marketed herb.','Herbs & Botanicals',5,false,'Do not self-prescribe extracts or doses; check interactions and avoid relying on marketing claims for stress, sleep, or thyroid concerns.'),
  ('turmeric-food-versus-supplement','Turmeric: Food Use Versus Supplements','How culinary use differs from concentrated products.','Herbs & Botanicals',5,false,'Enjoy turmeric in food if tolerated, but consult a clinician before using supplements, especially with medicines or gallbladder concerns.'),
  ('tulsi-safety-guide','Tulsi: Traditional Use and Product Caution','A non-promotional guide to evaluating Tulsi products.','Herbs & Botanicals',5,false,'Check ingredients and seek professional advice before use in pregnancy, with chronic conditions, or alongside medicines.'),
  ('triphala-safety-guide','Triphala: A Safety-First Overview','Traditional context without dosing or treatment claims.','Herbs & Botanicals',5,false,'Avoid using a multi-herb product as a substitute for evaluating persistent digestive symptoms or medication side effects.'),
  ('herb-quality-and-testing','Herb Quality, Testing, and Contamination','Why product quality matters for botanical products.','Herbs & Botanicals',5,false,'Use products with transparent labeling and independent quality information; report suspected adverse effects to a clinician.'),
  ('herbs-and-medication-interactions','Herbs and Medication Interactions','Why natural does not automatically mean risk-free.','Herbs & Botanicals',5,false,'Ask a pharmacist to review all medicines, over-the-counter products, and supplements together before starting a botanical.'),
  ('herbs-during-pregnancy','Herbs During Pregnancy and Breastfeeding','A precaution-focused overview.','Herbs & Botanicals',5,false,'Avoid starting herbal supplements without guidance from an obstetric clinician or qualified pharmacist.'),
  ('when-to-stop-a-supplement','When to Stop a Supplement and Seek Help','Recognizing safety signals when trying a new product.','Herbs & Botanicals',4,false,'Stop and seek prompt clinical advice for allergic symptoms, severe stomach symptoms, fainting, jaundice, or other concerning changes.'),
  ('tadasana-foundations','Tadasana Foundations','A beginner guide to Mountain Pose and supported standing.','Yoga & Asanas',5,true,'Use a wall or chair for support, keep knees comfortable, and stop for pain, dizziness, or instability.'),
  ('vrikshasana-supported','Supported Tree Pose','A balance practice with wall and chair options.','Yoga & Asanas',5,false,'Keep toes on the floor or hold support instead of forcing a one-leg balance.'),
  ('trikonasana-modifications','Triangle Pose With Modifications','How to make a standing side stretch more accessible.','Yoga & Asanas',5,false,'Use a chair or thigh support and avoid forcing the side bend or neck position.'),
  ('chair-yoga-introduction','Chair Yoga: A Gentle Starting Point','Ways to begin yoga with seated support.','Yoga & Asanas',5,false,'Choose stable furniture, move slowly, and ask a clinician or qualified instructor about needed adaptations.'),
  ('yoga-warm-up-basics','Yoga Warm-Up Basics','A practical preparation routine before gentle movement.','Yoga & Asanas',4,false,'Start with comfortable joint movement and easy breathing; avoid working through sharp pain.'),
  ('yoga-balance-safety','Balance Practice Safety','How to make balance work safer at home.','Yoga & Asanas',4,false,'Practise near stable support, clear trip hazards, and avoid unsupervised balance challenges after alcohol or sedating medicines.'),
  ('yoga-wrist-and-knee-options','Yoga Options for Sensitive Wrists and Knees','General modifications for common pressure points.','Yoga & Asanas',5,false,'Use props, reduce load, or choose a different posture; persistent joint pain deserves clinical evaluation.'),
  ('restorative-yoga-basics','Restorative Yoga Basics','A gentle approach to supported rest.','Yoga & Asanas',5,false,'Use comfortable props and leave a posture if it worsens pain, numbness, reflux, or breathlessness.'),
  ('yoga-during-pregnancy','Yoga During Pregnancy: Modification Matters','Why prenatal guidance and individualized advice are important.','Yoga & Asanas',5,false,'Seek clearance when needed and work with a prenatal-qualified instructor; avoid assuming a general class is appropriate.'),
  ('gentle-diaphragmatic-breathing','Gentle Diaphragmatic Breathing','A calm breathing practice without performance goals.','Pranayama & Meditation',4,true,'Keep the breath easy and stop if you feel light-headed, panicky, or unusually short of breath.'),
  ('nadi-shodhana-safety','Alternate-Nostril Breathing: Safety and Comfort','Traditional context with a conservative practice approach.','Pranayama & Meditation',5,false,'Avoid forceful breathing and prolonged holds; seek advice with respiratory symptoms, pregnancy concerns, or cardiovascular conditions.'),
  ('breath-retention-caution','Breath Retention: Why Caution Matters','A safety note on optional pauses and forced holds.','Pranayama & Meditation',4,false,'Do not force breath retention; choose normal breathing and stop if there is dizziness, discomfort, or anxiety.'),
  ('meditation-for-beginners','Meditation for Beginners','A short, practical introduction to attention practice.','Pranayama & Meditation',5,false,'Start with a brief, comfortable practice and seek mental-health support if meditation intensifies distress or traumatic memories.'),
  ('body-scan-practice','A Gentle Body Scan','A simple awareness practice for noticing comfort and tension.','Pranayama & Meditation',4,false,'Treat observations as information, not a diagnosis, and skip areas that feel overwhelming.'),
  ('mindful-walking-practice','Mindful Walking Practice','Combining attention with safe, ordinary movement.','Pranayama & Meditation',4,false,'Choose a safe route, stay aware of surroundings, and use usual mobility supports.'),
  ('meditation-expectations','Meditation Expectations and Common Myths','What a beginner can realistically expect.','Pranayama & Meditation',4,false,'Aim for consistency rather than a blank mind, and do not use meditation to delay care for severe anxiety or depression.'),
  ('breathing-and-anxiety-boundaries','Breathing Practices and Anxiety: Useful Boundaries','When calming exercises may need adaptation.','Pranayama & Meditation',5,false,'Return to normal breathing and seek professional support if an exercise increases panic, faintness, or distress.'),
  ('creating-meditation-space','Creating a Meditation Space','A low-cost setup for a regular practice.','Pranayama & Meditation',4,false,'Choose a comfortable, accessible place and keep the practice optional and adaptable.'),
  ('self-massage-comfort-care','Self-Massage as Comfort Care','A practical, non-therapeutic approach to gentle self-massage.','Traditional Wellness Practices',5,false,'Avoid injured, inflamed, numb, or broken skin and seek clinical advice for swelling, circulation, or clotting concerns.'),
  ('bath-and-soak-safety','Baths and Soaks: Comfort and Safety','How to use warmth safely for relaxation.','Traditional Wellness Practices',4,false,'Use safe water temperatures, prevent slips, and avoid prolonged heat with dizziness, pregnancy concerns, or health conditions.'),
  ('aromatics-and-sensitivities','Aromatics and Sensitivities','Using scents thoughtfully around allergies and pets.','Traditional Wellness Practices',4,false,'Avoid ingesting essential oils and stop using a scent if it triggers headache, wheeze, rash, or nausea.'),
  ('wellness-rituals-and-consistency','Wellness Rituals That Are Easy to Repeat','How to create comforting routines without perfectionism.','Traditional Wellness Practices',4,false,'Choose one short ritual that fits your day and let it support—not replace—medical care and basic needs.'),
  ('traditional-therapies-informed-consent','Traditional Therapies and Informed Consent','Questions to ask before hands-on or intensive practices.','Traditional Wellness Practices',5,false,'Ask about training, hygiene, ingredients, boundaries, costs, contraindications, and what to do if you feel unwell.'),
  ('heat-therapy-safety','Heat Therapy Safety','General precautions for warm compresses and similar comfort tools.','Traditional Wellness Practices',4,false,'Protect skin, limit heat exposure, and avoid heat over areas with reduced sensation unless a clinician advises otherwise.'),
  ('wellness-product-labels','Reading Wellness Product Labels','How to understand ingredient lists and marketing language.','Traditional Wellness Practices',4,false,'Look for complete ingredients and clear instructions, and avoid products that promise rapid cures or secret formulas.'),
  ('choosing-wellness-practitioner','Choosing a Wellness Practitioner','A consumer checklist for complementary services.','Traditional Wellness Practices',5,false,'Verify credentials where applicable and keep your medical team informed about therapies and products you use.'),
  ('sleep-schedule-basics','Sleep Schedule Basics','How regular timing supports a healthier sleep routine.','Sleep & Stress Management',5,true,'Keep wake time reasonably consistent and seek medical advice for persistent insomnia, loud snoring, or excessive daytime sleepiness.'),
  ('sleep-environment-guide','Creating a Sleep-Friendly Environment','Practical bedroom comfort and screen habits.','Sleep & Stress Management',4,false,'Aim for a quiet, relaxing setting and reduce late device use when feasible; adapt for caregiving and shift work realities.'),
  ('caffeine-and-sleep','Caffeine and Sleep','How timing can affect sleep for some people.','Sleep & Stress Management',4,false,'Notice your response and discuss persistent sleep problems with a clinician instead of escalating caffeine or supplements.'),
  ('stress-management-toolkit','A Practical Stress-Management Toolkit','Small evidence-informed self-care actions for demanding days.','Sleep & Stress Management',5,false,'Use movement, connection, rest, and professional support as needed; urgent mental-health symptoms need prompt help.'),
  ('worry-time-practice','Scheduling Worry Time','A structured reflection practice for repetitive thoughts.','Sleep & Stress Management',4,false,'If worry feels unmanageable or includes thoughts of self-harm, contact emergency or crisis support promptly.'),
  ('rest-without-productivity','Rest Without Productivity Pressure','Reframing rest as a basic need.','Sleep & Stress Management',4,false,'Choose a brief restorative activity and seek support when exhaustion persists despite adequate opportunity to sleep.'),
  ('social-connection-and-stress','Social Connection and Stress','Making room for supportive contact in a wellness plan.','Sleep & Stress Management',4,false,'Reach out to trusted people and use professional or crisis services when safety or mental health is at risk.'),
  ('shift-work-sleep-planning','Sleep Planning for Shift Work','Practical routine adjustments for nonstandard schedules.','Sleep & Stress Management',5,false,'Discuss persistent fatigue or safety-critical sleepiness with a clinician and avoid driving when too tired.'),
  ('screen-time-and-winding-down','Screen Time and Winding Down','A flexible guide to evening technology habits.','Sleep & Stress Management',4,false,'Experiment with a manageable screen-free interval rather than treating one rule as universally necessary.'),
  ('preventive-care-checklist','A Preventive Care Checklist','Why routine screening and vaccination matter alongside self-care.','Healthy Lifestyle & Prevention',5,true,'Follow locally appropriate screening and vaccination guidance with a licensed health professional.'),
  ('starting-physical-activity','Starting Physical Activity Safely','How to begin movement without an all-or-nothing plan.','Healthy Lifestyle & Prevention',5,false,'Start below your limit, progress gradually, and seek advice before a new program with symptoms or chronic conditions.'),
  ('tobacco-alcohol-wellness','Tobacco, Alcohol, and Wellness Goals','Why lifestyle change deserves evidence-based support.','Healthy Lifestyle & Prevention',5,false,'Use evidence-based cessation or alcohol-support services rather than relying on detox products or willpower alone.'),
  ('healthy-aging-habits','Healthy Aging Habits','Everyday actions that support function and connection over time.','Healthy Lifestyle & Prevention',5,false,'Include strength, balance, sleep, nutrition, connection, and routine health care while adapting to individual abilities.'),
  ('travel-wellness-basics','Travel Wellness Basics','Planning food, movement, sleep, and medicines while away.','Healthy Lifestyle & Prevention',4,false,'Carry essential medicines as prescribed and seek travel-specific medical advice when destinations or conditions require it.'),
  ('health-goals-without-extremes','Health Goals Without Extremes','A sustainable alternative to detoxes and drastic challenges.','Healthy Lifestyle & Prevention',4,false,'Set small observable actions and consult qualified professionals before restrictive eating, fasting, or intense exercise.'),
  ('family-wellness-routines','Family Wellness Routines','Building shared habits with flexibility and respect.','Healthy Lifestyle & Prevention',4,false,'Choose age-appropriate routines and ask pediatric or clinical professionals about individual health needs.'),
  ('preventing-falls-at-home','Preventing Falls at Home','Home-safety steps that complement balance and strength work.','Healthy Lifestyle & Prevention',5,false,'Review lighting, footwear, medicines, and hazards; seek assessment after a fall or new balance problem.'),
  ('health-information-checklist','A Checklist for Health Information Online','How to assess wellness claims before acting on them.','Healthy Lifestyle & Prevention',5,false,'Check who wrote the information, whether sources are cited, and whether a claim acknowledges uncertainty and risks.'),
  ('care-escalation-guide','When to Escalate From Self-Care to Clinical Care','Recognizing when a wellness concern needs professional assessment.','Healthy Lifestyle & Prevention',5,false,'Seek urgent help for severe symptoms, sudden change, chest pain, trouble breathing, confusion, or safety concerns.'),
  ('vaccination-and-wellness','Vaccination and Everyday Wellness','How preventive vaccination fits alongside personal wellness routines.','Healthy Lifestyle & Prevention',4,false,'Use official local guidance and a licensed clinician for vaccine decisions, especially with allergies, pregnancy, or immune conditions.'),
  ('medication-list-safety','Keeping an Accurate Medication and Supplement List','A simple preparation habit for safer clinical conversations.','Healthy Lifestyle & Prevention',4,false,'Record prescription medicines, over-the-counter products, herbs, and supplements, then bring the list to every clinical visit.'),
  ('whole-person-wellness-plan','Creating a Whole-Person Wellness Plan','A practical way to combine sleep, food, movement, connection, and care.','Healthy Lifestyle & Prevention',6,false,'Choose one goal in each area and review it with a clinician when health conditions, medicines, or pregnancy affect planning.')
)
INSERT INTO public.wisdom_articles
  (slug, title, excerpt, content, category, read_time_minutes, is_featured, is_published)
SELECT
  slug,
  title,
  excerpt,
  format(
    '# %s\n\n## Overview\n\n%s\n\n## Practical guidance\n\n%s\n\n## Traditional context and evidence\n\nAyurveda is a traditional system of wellness. Its concepts are presented here for education and reflection, not as diagnosis, treatment, or a substitute for medical care. Established health guidance should come from qualified clinicians and trusted public-health sources.\n\n## Safety\n\n%s\n\n## Further reading\n\n- NCCIH: https://www.nccih.nih.gov/health/ayurvedic-medicine-in-depth\n- WHO: https://www.who.int/news-room/fact-sheets/detail/self-care-health-interventions\n- CDC: https://www.cdc.gov/physical-activity-basics/benefits/index.html',
    title, excerpt, practical_guidance, practical_guidance
  ),
  category,
  read_time_minutes,
  is_featured,
  true
FROM articles
ON CONFLICT (slug) DO UPDATE
SET
  title = EXCLUDED.title,
  excerpt = EXCLUDED.excerpt,
  content = EXCLUDED.content,
  category = EXCLUDED.category,
  read_time_minutes = EXCLUDED.read_time_minutes,
  is_featured = EXCLUDED.is_featured;
